//! Native listing transition fixtures; no real listing/browser/account evidence.
async fn listing_fixture()->(PgConnection,Value){
    let(mut c,binding,_)=sync_fixture(json!([])).await;
    sqlx::raw_sql("ALTER TABLE jobs ADD COLUMN IF NOT EXISTS canonical_key text UNIQUE,ADD COLUMN IF NOT EXISTS content_identity varchar(64) UNIQUE,ADD COLUMN IF NOT EXISTS first_observed_at timestamptz,ADD COLUMN IF NOT EXISTS updated_at timestamptz DEFAULT clock_timestamp(),ADD COLUMN IF NOT EXISTS salary_range varchar(100),ADD COLUMN IF NOT EXISTS match_score numeric(5,2),ADD COLUMN IF NOT EXISTS match_explanation text;ALTER TABLE companies ADD COLUMN IF NOT EXISTS is_catch_all boolean NOT NULL DEFAULT false;DROP TABLE job_source_observations").execute(&mut c).await.unwrap();
    let source=include_str!("../../../../supabase/fresh_public/001_phase1_public.sql");let table=source.split("CREATE TABLE IF NOT EXISTS public.job_source_observations (").nth(1).unwrap().split("CREATE INDEX IF NOT EXISTS idx_observation_job").next().unwrap();sqlx::raw_sql(sqlx::AssertSqlSafe(format!("CREATE TABLE IF NOT EXISTS public.job_source_observations ({table}"))).execute(&mut c).await.unwrap();
    let work=execution_enqueue(&mut c,"823456789012").await;let mut work=work;work["status"]=json!("executing");work["binding"]=binding;work["revision"]=json!(2);work["lease_token"]=json!(Uuid::new_v4());work["lease_until"]=json!((chrono::Utc::now()+chrono::Duration::seconds(180)).to_rfc3339());browser_save(&mut c,&format!("apply_work:{}",work["id"].as_str().unwrap()),work.clone()).await;(c,work)
}
fn listing_report(work:&Value)->Value{json!({"kind":"job_facts","observed_url":work["url"],"requisition":work["requisition"],"job":{"requisition":work["requisition"],"title":"Rust Developer","company":"New Fictional Employer","location":"Remote","description":"Fictional Rust development role","skills":["Rust"],"experience_min":0.0,"experience_max":1.0,"posted_at":chrono::Utc::now().to_rfc3339(),"applicants_min":10,"applicants_max":10,"remote_type":"remote","evidence_sha256":"a".repeat(64)}})}
async fn listing_observe(c:&mut PgConnection,work:&Value,report:Value)->Result<Value>{automated_apply_agents::execution::discovery_observation::observe(c,sync_request(work),report).await}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_listing_observation_persists_source_identity_and_queues_only_factually_checked_preparation(){
    let(mut c,work)=listing_fixture().await;let observed=listing_observe(&mut c,&work,listing_report(&work)).await.unwrap();assert_eq!(observed["operation"],"prepare");assert_eq!(observed["stage"],"ELIGIBLE");assert_eq!(observed["admitted_actions"],json!([]));assert!(observed["packet_id"].is_null());let id=observed["job_id"].as_str().unwrap().parse::<Uuid>().unwrap();let job:Value=sqlx::query_scalar("SELECT to_jsonb(j) FROM jobs j WHERE id=$1").bind(id).fetch_one(&mut c).await.unwrap();assert_eq!(job["title"],"Rust Developer");assert_eq!(job["discovery_metadata"]["experience_min_years"],0.0);assert_eq!(sqlx::query_scalar::<_,i64>("SELECT count(*) FROM job_source_observations WHERE job_id=$1").bind(id).fetch_one(&mut c).await.unwrap(),1);assert!(observed["lease_token"].is_null());
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_listing_reobservation_preserves_canonical_owner_title_status_match_and_employer(){
    let(mut c,work)=listing_fixture().await;let first=listing_observe(&mut c,&work,listing_report(&work)).await.unwrap();let id=first["job_id"].as_str().unwrap().parse::<Uuid>().unwrap();sqlx::query("UPDATE jobs SET title='Owner retained title',status='shortlisted',match_score=88,match_explanation='Owner review retained' WHERE id=$1").bind(id).execute(&mut c).await.unwrap();let mut reread=work.clone();reread["revision"]=json!(10);browser_save(&mut c,&format!("apply_work:{}",work["id"].as_str().unwrap()),reread.clone()).await;let mut report=listing_report(&work);report["job"]["title"]=json!("New observed title");let observed=listing_observe(&mut c,&reread,report).await.unwrap();assert_eq!(observed["job_id"],first["job_id"]);let job:Value=sqlx::query_scalar("SELECT to_jsonb(j) FROM jobs j WHERE id=$1").bind(id).fetch_one(&mut c).await.unwrap();assert_eq!(job["title"],"Owner retained title");assert_eq!(job["status"],"shortlisted");assert_eq!(job["match_score"].as_f64(),Some(88.0));assert_eq!(job["match_explanation"],"Owner review retained");assert_eq!(job["discovery_metadata"]["title"],"New observed title");
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_listing_employer_conflict_is_reviewed_without_partial_company_or_observation_writes(){
    let(mut c,work)=listing_fixture().await;let first=listing_observe(&mut c,&work,listing_report(&work)).await.unwrap();let id=first["job_id"].as_str().unwrap().parse::<Uuid>().unwrap();let job_before:Value=sqlx::query_scalar("SELECT to_jsonb(j) FROM jobs j WHERE id=$1").bind(id).fetch_one(&mut c).await.unwrap();let before:Value=sqlx::query_scalar("SELECT jsonb_agg(to_jsonb(o) ORDER BY id) FROM job_source_observations o").fetch_one(&mut c).await.unwrap();let count:i64=sqlx::query_scalar("SELECT count(*) FROM companies").fetch_one(&mut c).await.unwrap();let mut reread=work.clone();reread["revision"]=json!(10);browser_save(&mut c,&format!("apply_work:{}",work["id"].as_str().unwrap()),reread.clone()).await;let mut report=listing_report(&work);report["job"]["company"]=json!("Conflicting Employer");let held=listing_observe(&mut c,&reread,report).await.unwrap();assert_eq!(held["reason"],"job_identity_requires_review");assert_eq!(held["status"],"waiting");assert_eq!(sqlx::query_scalar::<_,Value>("SELECT to_jsonb(j) FROM jobs j WHERE id=$1").bind(id).fetch_one(&mut c).await.unwrap(),job_before);assert_eq!(sqlx::query_scalar::<_,Value>("SELECT jsonb_agg(to_jsonb(o) ORDER BY id) FROM job_source_observations o").fetch_one(&mut c).await.unwrap(),before);assert_eq!(sqlx::query_scalar::<_,i64>("SELECT count(*) FROM companies").fetch_one(&mut c).await.unwrap(),count);
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_listing_unknown_applicants_hold_before_ingestion_and_notice_deduplicates_without_changing_policy(){
    let(mut c,work)=listing_fixture().await;let config=browser_pref(&mut c,"application_queue_policy").await;let count:i64=sqlx::query_scalar("SELECT count(*) FROM jobs").fetch_one(&mut c).await.unwrap();let mut report=listing_report(&work);report["job"]["applicants_max"]=Value::Null;report["job"]["applicants_min"]=json!(100);let held=listing_observe(&mut c,&work,report).await.unwrap();assert_eq!(held["reason"],"applicant_count_requires_review");assert_eq!(held["status"],"waiting");assert_eq!(sqlx::query_scalar::<_,i64>("SELECT count(*) FROM jobs").fetch_one(&mut c).await.unwrap(),count);assert_eq!(browser_pref(&mut c,"application_queue_policy").await,config);assert_eq!(sqlx::query_scalar::<_,i64>("SELECT count(*) FROM owner_notifications WHERE kind='automation_policy_question'").fetch_one(&mut c).await.unwrap(),1);
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_listing_failed_source_ack_rolls_back_company_job_work_and_events(){
    let(mut c,work)=listing_fixture().await;let before=browser_snapshot(&mut c).await;let jobs:i64=sqlx::query_scalar("SELECT count(*) FROM jobs").fetch_one(&mut c).await.unwrap();let companies:i64=sqlx::query_scalar("SELECT count(*) FROM companies").fetch_one(&mut c).await.unwrap();sqlx::raw_sql("CREATE FUNCTION fixture_listing_drop() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RETURN NULL; END $$;CREATE TRIGGER fixture_listing_drop BEFORE INSERT ON job_source_observations FOR EACH ROW EXECUTE FUNCTION fixture_listing_drop()").execute(&mut c).await.unwrap();assert_eq!(listing_observe(&mut c,&work,listing_report(&work)).await.unwrap_err(),Failure("execution_write_ack_failed"));assert_eq!(browser_snapshot(&mut c).await,before);assert_eq!(sqlx::query_scalar::<_,i64>("SELECT count(*) FROM jobs").fetch_one(&mut c).await.unwrap(),jobs);assert_eq!(sqlx::query_scalar::<_,i64>("SELECT count(*) FROM companies").fetch_one(&mut c).await.unwrap(),companies);sqlx::raw_sql("DROP TRIGGER fixture_listing_drop ON job_source_observations;DROP FUNCTION fixture_listing_drop()").execute(&mut c).await.unwrap();
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_listing_transport_retries_are_bounded_and_never_retry_a_spent_or_packet_bound_form(){
    let(mut c,work)=listing_fixture().await;
    for kind in ["retry","exhausted","spent","packet"]{let mut value=work.clone();if kind=="exhausted"{value["transport_retry_count"]=json!(3);}if kind=="spent"{value["admitted_actions"]=json!([{"fingerprint":"apply:spent"}]);}if kind=="packet"{value["packet_id"]=json!(Uuid::new_v4());}browser_save(&mut c,&format!("apply_work:{}",work["id"].as_str().unwrap()),value.clone()).await;let result=listing_observe(&mut c,&value,json!({"kind":"failed","reason":"backend_timeout"})).await.unwrap();assert_eq!(result["status"],if kind=="retry"{"queued"}else{"waiting"});assert_eq!(result["admitted_actions"],value["admitted_actions"]);assert_eq!(result["packet_id"],value["packet_id"]);}
}
